def convert(c):
    const=[]; trans=[]; klist=[]
    for i in range(20):
        if dims[i]==1:
            const.append(np.array([-1.])); trans.append(np.array([[2.]])); klist.append([0.])
        else:
            const.append((np.array([-1.,0,0,0])-m)@W); trans.append(W/scales[i])
            klist.append([means[i]-scales[i]]+[means[i]+scales[i]*k for k in knots])
    main=[np.zeros(d) for d in dims]
    pair={}
    ic=float(c[0])
    for t,d in enumerate(desc[1:],1):
        if c[t]==0: continue
        if d[0]=='main':
            i,a=d[1:]; ic+=c[t]*const[i][a]; main[i]+=c[t]*trans[i][:,a]
        else:
            i,j,a,b=d[1:]
            ic+=c[t]*const[i][a]*const[j][b]
            main[i]+=c[t]*trans[i][:,a]*const[j][b]
            main[j]+=c[t]*trans[j][:,b]*const[i][a]
            if (i,j) not in pair: pair[(i,j)]=np.zeros((dims[i],dims[j]))
            pair[(i,j)]+=c[t]*np.outer(trans[i][:,a],trans[j][:,b])
    ic-=main[0][0]*klist[0][0]
    terms=[]
    ints=[]
    for i in range(20):
        for a,cv in enumerate(main[i]):
            if abs(cv)>1e-10: terms.append((i,a,float(cv)))
    for (i,j),mat in pair.items():
        for a in range(dims[i]):
            for b in range(dims[j]):
                if abs(mat[a,b])>1e-10: ints.append((i,j,a,b,float(mat[a,b])))
    return ic,terms,ints,klist

